/**
 * A hierarchy opened level by level, with one item picked (`design/components/tree.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  cell,
  derived,
  elementRef,
  mountEffect,
  uniqueId,
  useMember,
  type Each,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/tree.module.css'
import { Spinner, type SpinnerProps } from './Spinner'
import { TreeNode, type TreeNodeProps } from './TreeNode'

export interface TreeItem {
  /** Unique in the tree. `change`, `expandedChange` and `loadMore` report it. */
  id: string
  label: string
  /** One supporting line under the label. */
  description?: string
  /** The items under it. An item with one or more is a branch. */
  children?: TreeItem[]
  /**
   * A branch whose items the app loads when it is first opened. With no `children` the
   * branch opens onto nothing until the app passes them.
   */
  hasChildren?: boolean
  /** The branch's level is loading. An open branch draws one busy row under itself. */
  loading?: boolean
  /** The branch has more items than `children` holds: a last row asks for them. */
  hasMore?: boolean
  /** The item takes no key and no press, the arrow keys pass over it, and a branch stays closed. */
  disabled?: boolean
}

export interface TreeMessages {
  /** What a level says while it loads. */
  loading: string
  /** The row that asks for more of a level. */
  loadMore: string
}

/** A hierarchy opened level by level, with one item picked: the inputs it takes, by the React member's prop names. */
export interface TreeProps {
  /**
   * The branches open at first, while the tree holds the set.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * The item selected at first, while the tree holds the selection.
   */
  defaultValue?: string
  /**
   * The open branches by id. Controlled when given; without it the tree holds the set.
   */
  expanded?: ReadonlySet<string>
  /**
   * The top level has more items than `items` holds: a last row asks for them.
   */
  hasMore?: boolean
  /**
   * The top level.
   */
  items: TreeItem[]
  /**
   * Names the tree for a reader: "Organization units", not "Tree".
   */
  label: string
  /**
   * The top level is loading, as an item's `loading` says of its own level.
   */
  loading?: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: TreeMessages
  /**
   * The selected item's id. Controlled when given, and `null` selects nothing.
   */
  value?: string | null
}

/** A hierarchy opened level by level, with one item picked. */
@Component({
  selector: 'pm-tree',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, Spinner, TreeNode],
  // prettier-ignore
  template: `<ul
[attr.class]="e1()"
role="tree"
[attr.aria-label]="e2()"
[attr.aria-busy]="e3()"
data-member="tree"
(focusin)="h1($event)"
(focusout)="h2($event)"
(keydown)="h3($event)"
(click)="h4($event)"
[pmRef]="root"
>@for (child of e4(); track e5(child)) {<li
pmTreeNode
[item]="e6(child)"
[level]="e7()"
[open]="e8()"
[selected]="e9()"
[messages]="e10()"
></li>}
@if (e11()) {<!-- more -->
<li
[attr.class]="e12()"
role="treeitem"
[attr.aria-labelledby]="e13()"
aria-selected="false"
[attr.aria-busy]="e14()"
data-tree-part="more"
><div
[attr.class]="e15()"
[style.--pm-tree-level]="e16()"
data-tree-part="row"
[attr.data-busy]="e17()"
><span
[attr.class]="e18()"
>@if (e19()) {<pm-spinner
size="sm"
[label]="e20()"
></pm-spinner>}</span>
<span
[attr.class]="e21()"
><span
[attr.class]="e22()"
[attr.id]="e13()"
>{{ e23() }}</span></span></div></li>} @else if (e24()) {<!-- busy -->
<li
[attr.class]="e25()"
role="none"
><div
[attr.class]="e26()"
[style.--pm-tree-level]="e27()"
[attr.data-busy]="e28()"
><span
[attr.class]="e29()"
><pm-spinner
size="sm"
[label]="e30()"
></pm-spinner></span>
<span
[attr.class]="e31()"
><span
[attr.class]="e32()"
aria-hidden="true"
>{{ e33() }}</span></span></div></li>}</ul>`,
})
export class Tree {
  /**
   * The branches open at first, while the tree holds the set.
   */
  readonly defaultExpanded = input<TreeProps['defaultExpanded']>(undefined)
  /**
   * The item selected at first, while the tree holds the selection.
   */
  readonly defaultValue = input<TreeProps['defaultValue']>(undefined)
  /**
   * The open branches by id. Controlled when given; without it the tree holds the set.
   */
  readonly expanded = input<TreeProps['expanded']>(undefined)
  /**
   * The top level has more items than `items` holds: a last row asks for them.
   */
  readonly hasMore = input<Exclude<TreeProps['hasMore'], undefined>, TreeProps['hasMore']>(false, {
    transform: (value: TreeProps['hasMore']) => (value === undefined ? false : value),
  })
  /**
   * The top level.
   */
  readonly items = input.required<TreeProps['items']>()
  /**
   * Names the tree for a reader: "Organization units", not "Tree".
   */
  readonly label = input.required<TreeProps['label']>()
  /**
   * The top level is loading, as an item's `loading` says of its own level.
   */
  readonly loading = input<Exclude<TreeProps['loading'], undefined>, TreeProps['loading']>(false, {
    transform: (value: TreeProps['loading']) => (value === undefined ? false : value),
  })
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  readonly messages = input<Exclude<TreeProps['messages'], undefined>, TreeProps['messages']>(
    (() => ({ loading: 'Loading', loadMore: 'Load more' }))(),
    {
      transform: (value: TreeProps['messages']) =>
        value === undefined ? (() => ({ loading: 'Loading', loadMore: 'Load more' }))() : value,
    },
  )
  /**
   * The selected item's id. Controlled when given, and `null` selects nothing.
   */
  readonly value = input<TreeProps['value']>(undefined)
  /**
   * Called with the id of the item a reader selects.
   */
  readonly onChange = output<string>({ alias: 'change' })
  /**
   * Called with the next set of open branches, controlled or not.
   */
  readonly onExpandedChange = output<ReadonlySet<string>>({ alias: 'expandedChange' })
  /**
   * Called with a branch's id, or `null` for the top level, when a reader asks for more.
   */
  readonly onLoadMore = output<string | null>({ alias: 'loadMore' })
  protected readonly $ = useMember({
    events: ['change', 'expandedChange', 'loadMore'],
    props: {
      defaultExpanded: () => this.defaultExpanded(),
      defaultValue: () => this.defaultValue(),
      expanded: () => this.expanded(),
      hasMore: () => this.hasMore(),
      items: () => this.items(),
      label: () => this.label(),
      loading: () => this.loading(),
      messages: () => this.messages(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly ownExpanded = cell(() => this.$p.defaultExpanded ?? new Set<string>())
  protected readonly ownValue = cell(() => (this.$p.defaultValue ?? null) as string | null)
  protected readonly placed = cell(() => false)
  protected readonly held = cell(() => false)
  protected readonly asked = cell(() => null as { parent: string | null; count: number } | null)
  protected readonly moving = cell(() => false)
  protected readonly root = elementRef<HTMLElement>()
  protected readonly open = derived(() => this.$p.expanded ?? this.ownExpanded.value)
  protected readonly selected = derived(() =>
    this.$p.value === undefined ? this.ownValue.value : this.$p.value,
  )
  protected readonly shownItems = derived(() =>
    (() => {
      const seen: TreeItem[] = []
      const walk = (level: readonly TreeItem[]): void => {
        for (const item of level) {
          seen.push(item)
          if (item.disabled !== true && this.open.value.has(item.id)) walk(item.children ?? [])
        }
      }
      walk(this.$p.items)
      return seen
    })(),
  )
  protected readonly branchOf = derived(() => (id: string): void => {
    const item = this.shownItems.value.find((candidate) => candidate.id === id)
    if ((item?.children?.length ?? 0) === 0 && item?.hasChildren !== true)
      throw new Error(`"${item?.label ?? id}" is not a branch, so it does not open or close.`)
  })
  protected readonly rowsOf = derived(
    () =>
      (tree: HTMLElement): HTMLElement[] =>
        Array.from(
          tree.querySelectorAll<HTMLElement>('[role="treeitem"]:not([aria-disabled="true"])'),
        ),
  )
  protected readonly parentOf = derived(
    () =>
      (row: Element): string | null =>
        row.parentElement?.closest('[role="treeitem"]')?.getAttribute('data-tree-item') ?? null,
  )
  protected readonly levelOf = derived(
    () =>
      (tree: HTMLElement, parent: string | null): Element | null =>
        parent === null
          ? tree
          : (Array.from(tree.querySelectorAll('[role="treeitem"]'))
              .find((row) => row.getAttribute('data-tree-item') === parent)
              ?.querySelector(':scope > [role="group"]') ?? null),
  )
  protected readonly itemsIn = derived(
    () =>
      (list: Element): HTMLElement[] =>
        Array.from(list.children).filter(
          (child): child is HTMLElement =>
            child instanceof HTMLElement &&
            child.matches('[role="treeitem"]') &&
            !child.matches('[data-tree-part="more"]'),
        ),
  )
  protected readonly stopOf = derived(() => (tree: HTMLElement): HTMLElement | null => {
    const rows = this.rowsOf.value(tree)
    const now = this.placed.value
      ? rows.find((row) => row.getAttribute('tabindex') === '0')
      : undefined
    return (
      now ?? rows.find((row) => row.getAttribute('aria-selected') === 'true') ?? rows[0] ?? null
    )
  })
  protected readonly rove = derived(() => (tree: HTMLElement, stop: HTMLElement | null) => {
    for (const row of Array.from(tree.querySelectorAll<HTMLElement>('[role="treeitem"]'))) {
      if (row !== stop && row.getAttribute('aria-disabled') === 'true') {
        row.removeAttribute('tabindex')
        continue
      }
      const wanted = row === stop ? '0' : '-1'
      if (row.getAttribute('tabindex') !== wanted) row.setAttribute('tabindex', wanted)
    }
  })
  protected readonly settle = derived(() => () => {
    const tree = this.root.value as HTMLElement | null
    if (tree === null) return
    const lost = this.held.value && !tree.contains(document.activeElement)
    const request = this.asked.value
    let to: HTMLElement | null = null
    if (request !== null) {
      const list = this.levelOf.value(tree, request.parent)
      const found = list === null ? [] : this.itemsIn.value(list)
      if (list === null) this.asked.value = null
      else if (found.length > request.count) {
        if (this.held.value)
          to =
            found
              .slice(request.count)
              .find((row) => row.matches('[role="treeitem"]:not([aria-disabled="true"])')) ??
            this.stopOf.value(tree)
        this.asked.value = null
      }
    }
    if (to === null && lost) to = this.stopOf.value(tree)
    if (to === null) {
      this.rove.value(tree, this.stopOf.value(tree))
      return
    }
    this.rove.value(tree, to)
    this.moving.value = true
    to.focus()
    this.moving.value = false
  })
  protected readonly ask = derived(() => (row: HTMLElement) => {
    const list = row.parentElement
    if (list === null || row.getAttribute('aria-busy') === 'true') return
    const parent = this.parentOf.value(row)
    this.asked.value = { parent, count: this.itemsIn.value(list).length }
    this.$.emit(this.onLoadMore, 'onLoadMore', parent)
  })
  protected readonly toggle = derived(() => (id: string) => {
    const next = new Set(this.open.value)
    if (next.has(id)) next.delete(id)
    else next.add(id)
    this.ownExpanded.value = next
    this.$.emit(this.onExpandedChange, 'onExpandedChange', next)
  })
  protected readonly choose = derived(() => (id: string) => {
    if (id === this.selected.value) return
    this.ownValue.value = id
    this.$.emit(this.onChange, 'onChange', id)
  })
  protected readonly focusIn = derived(() => (event: FocusEvent) => {
    const tree = this.root.value as HTMLElement | null
    const row =
      event.target instanceof Element
        ? event.target.closest<HTMLElement>('[role="treeitem"]')
        : null
    if (tree === null || row === null) return
    this.held.value = true
    this.placed.value = true
    const request = this.asked.value
    if (
      !this.moving.value &&
      !(
        request !== null &&
        row.matches('[data-tree-part="more"]') &&
        this.parentOf.value(row) === request.parent
      )
    )
      this.asked.value = null
    this.rove.value(tree, row)
  })
  protected readonly focusOut = derived(() => (event: FocusEvent) => {
    const tree = this.root.value as HTMLElement | null
    const row = event.target
    queueMicrotask(() => {
      if (tree === null || !(row instanceof Element) || !row.isConnected) return
      if (!tree.contains(document.activeElement)) this.held.value = false
    })
  })
  protected readonly keyDown = derived(() => (event: KeyboardEvent) => {
    const tree = this.root.value as HTMLElement | null
    const here =
      event.target instanceof Element
        ? event.target.closest<HTMLElement>('[role="treeitem"]')
        : null
    if (tree === null || here === null || event.altKey || event.ctrlKey || event.metaKey) return
    const rows = this.rowsOf.value(tree)
    const at = rows.indexOf(here)
    const rtl = getComputedStyle(tree).direction === 'rtl'
    const inward = rtl ? 'ArrowLeft' : 'ArrowRight'
    const outward = rtl ? 'ArrowRight' : 'ArrowLeft'
    const id = here.matches('[role="treeitem"]:not([aria-disabled="true"])')
      ? here.getAttribute('data-tree-item')
      : null
    const state = here.getAttribute('aria-expanded')
    let to: HTMLElement | null | undefined = null
    switch (event.key) {
      case 'ArrowDown':
        to = rows[at + 1]
        break
      case 'ArrowUp':
        to = at > 0 ? rows[at - 1] : null
        break
      case 'Home':
        to = rows[0]
        break
      case 'End':
        to = rows[rows.length - 1]
        break
      case inward:
        if (id !== null && state === 'false') this.toggle.value(id)
        else if (state === 'true')
          to = here.querySelector<HTMLElement>(
            ':scope > [role="group"] > [role="treeitem"]:not([aria-disabled="true"])',
          )
        break
      case outward:
        if (id !== null && state === 'true') this.toggle.value(id)
        else
          to = here.parentElement?.closest<HTMLElement>(
            '[role="treeitem"]:not([aria-disabled="true"])',
          )
        break
      case 'Enter':
      case ' ':
        if (here.matches('[data-tree-part="more"]')) this.ask.value(here)
        else if (id !== null) this.choose.value(id)
        break
      default:
        return
    }
    event.preventDefault()
    if (to === null || to === undefined) return
    this.rove.value(tree, to)
    to.focus()
  })
  protected readonly press = derived(() => (event: MouseEvent) => {
    const target = event.target instanceof Element ? event.target : null
    const row = target?.closest('[data-tree-part="row"]')?.parentElement ?? null
    if (
      target === null ||
      row === null ||
      !row.matches('[role="treeitem"]:not([aria-disabled="true"])')
    )
      return
    const id = row.getAttribute('data-tree-item')
    if (row.matches('[data-tree-part="more"]')) this.ask.value(row)
    else if (id === null) return
    else if (target.closest('[data-tree-part="toggle"]') !== null) this.toggle.value(id)
    else this.choose.value(id)
  })
  private release1: (() => void) | undefined
  private release2: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.$p.label
  }

  protected e3() {
    return this.$p.loading ? true : undefined
  }

  protected h1($event: FocusEvent): void {
    this.focusIn.value($event)
  }

  protected h2($event: FocusEvent): void {
    this.focusOut.value($event)
  }

  protected h3($event: KeyboardEvent): void {
    this.keyDown.value($event)
  }

  protected h4($event: MouseEvent): void {
    this.press.value($event)
  }

  e4() {
    return this.$p.items
  }

  protected e5(child: Each<ReturnType<Tree['e4']>>) {
    return child.id
  }

  protected e6(child: Each<ReturnType<Tree['e4']>>): TreeNodeProps['item'] {
    return child
  }

  protected e7(): TreeNodeProps['level'] {
    return 0
  }

  protected e8(): TreeNodeProps['open'] {
    return this.open.value
  }

  protected e9(): TreeNodeProps['selected'] {
    return this.selected.value
  }

  protected e10(): TreeNodeProps['messages'] {
    return this.$p.messages
  }

  protected e11() {
    return this.$p.hasMore
  }

  protected e12() {
    if (!this.$p.hasMore) return undefined as never
    return styles.item
  }

  protected e13() {
    if (!this.$p.hasMore) return undefined as never
    return `${this.uid}-more`
  }

  protected e14() {
    if (!this.$p.hasMore) return undefined as never
    return this.$p.loading ? true : undefined
  }

  protected e15() {
    if (!this.$p.hasMore) return undefined as never
    return styles.row
  }

  protected e16() {
    if (!this.$p.hasMore) return undefined as never
    return 0
  }

  protected e17() {
    if (!this.$p.hasMore) return undefined as never
    return this.$p.loading ? '' : undefined
  }

  protected e18() {
    if (!this.$p.hasMore) return undefined as never
    return styles.slot
  }

  protected e19() {
    if (!this.$p.hasMore) return undefined as never
    return this.$p.loading
  }

  protected e20(): SpinnerProps['label'] {
    if (!this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return this.$p.messages.loading
  }

  protected e21() {
    if (!this.$p.hasMore) return undefined as never
    return styles.text
  }

  protected e22() {
    if (!this.$p.hasMore) return undefined as never
    return styles.more
  }

  protected e23() {
    if (!this.$p.hasMore) return undefined as never
    return this.$p.loading ? this.$p.messages.loading : this.$p.messages.loadMore
  }

  protected e24() {
    if (this.$p.hasMore) return undefined as never
    return this.$p.loading
  }

  protected e25() {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return styles.item
  }

  protected e26() {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return styles.row
  }

  protected e27() {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return 0
  }

  protected e28() {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return ''
  }

  protected e29() {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return styles.slot
  }

  protected e30(): SpinnerProps['label'] {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return this.$p.messages.loading
  }

  protected e31() {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return styles.text
  }

  protected e32() {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return styles.status
  }

  protected e33() {
    if (this.$p.hasMore) return undefined as never
    if (!this.$p.loading) return undefined as never
    return this.$p.messages.loading
  }

  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.settle.value()
    }
    const mutation = typeof MutationObserver === 'undefined' ? undefined : new MutationObserver(run)
    for (const element of [this.root.value])
      if (element)
        mutation?.observe(element, {
          childList: true,
          characterData: true,
          subtree: true,
          attributeFilter: ['aria-selected', 'aria-disabled'],
        })
    this.release1 = () => {
      mutation?.disconnect()
    }
    run()
  }

  private effect2(): void {
    this.release2?.()
    const ran = agentMember({
      member: 'Tree',
      element: () => this.root.value,
      state: () => ({
        value: this.selected.value ?? null,
        expanded: [...this.open.value],
        items: this.shownItems.value.map((item) => ({
          id: item.id,
          label: item.label,
          ...(item.disabled === true ? { disabled: true } : {}),
        })),
        loading: this.$p.loading,
      }),
      actions: {
        choose: { argument: 'id', run: (value) => this.choose.value(value) },
        expand: {
          argument: 'id',
          run: (value) => (
            this.branchOf.value(value),
            this.open.value.has(value) || this.toggle.value(value)
          ),
        },
        collapse: {
          argument: 'id',
          run: (value) => (
            this.branchOf.value(value),
            this.open.value.has(value) && this.toggle.value(value)
          ),
        },
      },
    })
    this.release2 = () => {
      ran()
    }
  }
}
